const src = $('Publish Webhook').first().json.body ?? $('Publish Webhook').first().json;
const lang = src.meta.lang_code || 'de';
const blocks = (src.blocks || []).map((b) => {
  if (b.kind !== 'title' && b.kind !== 'text') return b;
  const out = { kind: b.kind, [lang]: b.raw ?? b[lang] ?? '' };
  if (b.heading_level != null) out.heading_level = b.heading_level;
  return out;
});
return [{
  json: {
    slug: src.slug,
    meta: src.meta,
    source_lang: lang,
    title: src.meta.title,
    blocks,
    translate_items: blocks.flatMap((b, i) =>
      b.kind === 'title' || b.kind === 'text' ? [{ index: i, kind: b.kind, text: b[lang] }] : []
    ),
  },
}];

