const src = $('Publish Webhook').first().json.body ?? $('Publish Webhook').first().json;
const slug = src.slug;
const VIDEO_RE = /\.(mp4|mov|m4v|webm|avi|mkv|mpeg|mpg)$/i;
const videos = [];
const seen = new Set();
for (const b of src.blocks || []) {
  const m = b.media || {};
  const name = m.source_filename || '';
  const isVideo = b.kind === 'video' || m.kind === 'video' || VIDEO_RE.test(name);
  if (!isVideo || !name || seen.has(name)) continue;
  seen.add(name);
  videos.push({ filename: name, path: `/syndicator/${slug}/source/${name}`, slug });
}
return [{ json: { slug, videos, youtubeIds: {}, hasVideos: videos.length > 0 } }];

const uploads = $input.all();
const sources = $('Split Local Videos').all();
const youtubeIds = {};
for (let i = 0; i < uploads.length; i++) {
  const j = sources[i] && sources[i].json;
  const fn = j && (j.filename || (j.videos && j.videos.filename));
  const id = uploads[i].json.id || uploads[i].json.uploadId;
  if (fn && id) youtubeIds[fn] = id;
}
const listed = $('List Local Videos').first().json;
return [{ json: { slug: listed.slug, youtubeIds, hasVideos: true } }];

function from(name) {
  try { return $(name).first().json; } catch (e) { return {}; }
}
const hook = $('Publish Webhook').first().json.body ?? $('Publish Webhook').first().json;
const assembled = $('Assemble Multilingual Blocks').first().json;
const ytMap = Object.assign({}, from('List Local Videos').youtubeIds || {}, from('Merge Video IDs').youtubeIds || {});
const VIDEO_RE = /\.(mp4|mov|m4v|webm|avi|mkv|mpeg|mpg)$/i;
const sourceLang = assembled.source_lang || hook.meta?.lang_code || 'de';
function withoutLang(url) {
  return String(url || '').replace(/\/(de|en|es|fr|it|arrr)(?=\/posts\/)/i, '');
}
function absUrl(file) {
  const base = withoutLang(hook.post_url).replace(/\/?$/, '/');
  return base + String(file || '').replace(/^\//, '');
}
function featuredName(header) {
  const n = String(header || '').trim();
  if (!n) return '';
  const ext = n.includes('.') ? n.slice(n.lastIndexOf('.')) : '.jpg';
  return 'featured' + ext;
}
function escapeHtml(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function ytIframe(id) {
  return '<div class="video"><iframe src="https://www.youtube.com/embed/' + id + '" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>';
}
function mdToHtml(text) {
  let s = String(text || '');
  s = s.replace(/\{\{<\s*youtube\s+([^>\s]+)\s*>\}\}/g, (_, id) => ytIframe(id.trim()));
  s = s.replace(/\{\{<\s*video\s+src="([^"]+)"\s*>\}\}/g, (_, file) => {
    const id = ytMap[file];
    return id ? ytIframe(id) : '';
  });
  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_, alt, file) => {
    if (VIDEO_RE.test(file)) {
      const id = ytMap[file];
      return id ? ytIframe(id) : '';
    }
    return '<img src="' + escapeHtml(absUrl(file)) + '" alt="' + escapeHtml(alt) + '">';
  });
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  const lines = s.split('\n');
  const out = [];
  let para = [];
  const flush = () => {
    if (!para.length) return;
    const t = para.join('\n').trim();
    if (t) out.push('<p>' + t.replace(/\n/g, '<br>') + '</p>');
    para = [];
  };
  for (const line of lines) {
    const h = /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) { flush(); const n = h[1].length; out.push('<h' + n + '>' + h[2] + '</h' + n + '>'); continue; }
    if (/^<(div|iframe|img|h\d)/.test(line.trim())) { flush(); out.push(line); continue; }
    if (!line.trim()) { flush(); continue; }
    para.push(line);
  }
  flush();
  return out.join('\n');
}
function plain(text) {
  return String(text || '')
    .replace(/\{\{<[^>]+>\}\}/g, '')
    .replace(/!\[[^\]]*\]\([^)]+\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/[#*_`>]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
const lang = 'en';
const parts = [];
for (const b of assembled.blocks || []) {
  if (b.kind === 'title' || b.kind === 'text') {
    const text = b[lang] || (sourceLang === 'en' ? (b.raw || '') : '');
    const html = mdToHtml(text);
    if (html) parts.push(html);
    continue;
  }
  if (b.kind === 'youtube' && b.media && b.media.youtube_id) {
    parts.push(ytIframe(b.media.youtube_id));
    continue;
  }
  const m = b.media || {};
  const name = m.source_filename || '';
  if (b.kind === 'video' || m.kind === 'video' || VIDEO_RE.test(name)) {
    const id = ytMap[name];
    if (id) parts.push(ytIframe(id));
    continue;
  }
  if (name) {
    const alt = sourceLang === 'en' ? (m.alt || '') : '';
    parts.push('<img src="' + escapeHtml(absUrl(name)) + '" alt="' + escapeHtml(alt) + '">');
  }
}
const title = (assembled.titles && assembled.titles.en) || (sourceLang === 'en' ? (hook.meta.title || '') : '');
let subtitle = (assembled.summaries && assembled.summaries.en) || (sourceLang === 'en' ? (hook.meta.summary || '') : '');
if (!subtitle) {
  const first = (assembled.blocks || []).find((b) => b.kind === 'text' && b.en);
  subtitle = plain(first && first.en);
  if (subtitle.length > 280) subtitle = subtitle.slice(0, 277).replace(/\s+\S*$/, '') + '…';
}
return [{ json: {
  title,
  subtitle,
  contentHtml: parts.join('\n'),
  sourceUrl: withoutLang(hook.post_url),
  coverImageUrl: hook.header_source ? absUrl(featuredName(hook.header_source)) : '',
  idempotencyKey: hook.slug,
  slug: hook.slug,
} }];

function errText(item) {
  const e = item?.error ?? item?.json?.error;
  if (!e) return '';
  if (typeof e === 'string') return e;
  return [e.message, e.description, e.httpCode, JSON.stringify(e)].filter(Boolean).join(' ');
}
const item = $input.first();
const text = errText(item);
const ok = !text || /404|not found|not_found/i.test(text);
if (!ok) return [];
return [{ json: { narrareachOk: true } }];
